<script setup>
import { onBeforeUnmount, onMounted, ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { apiRequest } from "../api/client.js";
import { useAuth } from "../stores/auth.js";
const emit=defineEmits(["change"]);const auth=useAuth();const items=ref([]),error=ref(""),busy=ref("");let controller,timer,disposed=false,loading=false;
async function load(){if(loading||disposed)return;loading=true;controller=new AbortController();try{const result=await apiRequest('/pool/release-reviews',{signal:controller.signal});if(!disposed){items.value=result.items;error.value=""}}catch(cause){if(cause.name!=="AbortError"&&!disposed)error.value=cause.message||"待确认记录加载失败"}finally{loading=false}}
async function resolve(item,unused){if(busy.value)return;try{await ElMessageBox.confirm(unused?'请确认该地址没有绑定任何业务。确认后它会重新进入可领取库存。':'确认该地址实际已经使用，继续保留给原项目，不再重新发放。',unused?'确认未使用并归还':'确认已使用',{confirmButtonText:unused?'确认未使用，归还':'确认已使用',cancelButtonText:'暂不处理',type:'warning'})}catch{return}busy.value=item.lease_id;try{await apiRequest(`/pool/release-reviews/${encodeURIComponent(item.lease_id)}/resolve`,{method:'POST',body:{unused},csrfToken:auth.state.csrfToken});ElMessage.success('分配记录已核实');await load();emit('change')}catch(cause){ElMessage.error(cause.message||'核实失败，请刷新记录')}finally{busy.value=''}}
function schedule(){clearTimeout(timer);if(disposed||document.hidden||!navigator.onLine)return;timer=setTimeout(async()=>{await load();schedule()},30000)}
function wake(){load();schedule()}
onMounted(()=>{load();schedule();document.addEventListener('visibilitychange',wake);window.addEventListener('online',wake);window.addEventListener('offline',schedule)});onBeforeUnmount(()=>{disposed=true;controller?.abort();clearTimeout(timer);document.removeEventListener('visibilitychange',wake);window.removeEventListener('online',wake);window.removeEventListener('offline',schedule)});
</script>
<template><section v-if="items.length||error" class="release-reviews"><h3>有 {{items.length}} 个到期地址需要核实</h3><p>程序没有确认使用，系统无法判断业务是否成功。这些地址已暂停分配，旧访问凭据已失效。</p><p v-if="error" role="alert">{{error}}</p><div v-for="item in items" :key="item.lease_id" class="review-row"><div><strong>{{item.address}}</strong><span>领取项目：{{item.project}}</span></div><div><button :disabled="Boolean(busy)" @click="resolve(item,false)">确认已使用</button><button :disabled="Boolean(busy)" @click="resolve(item,true)">确认未使用并归还</button></div></div></section></template>
<style scoped>.release-reviews{padding:18px;border:1px solid var(--border);background:var(--warning-soft);border-radius:9px;margin:0 0 20px}.release-reviews h3{font-size:14px;margin:0;color:var(--warning)}.release-reviews p{font-size:11px;margin:9px 0 16px;color:var(--text-secondary);line-height:1.8}.review-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 0;border-top:1px solid var(--border)}.review-row strong{display:block;font-size:12px;font-weight:500;overflow-wrap:anywhere}.review-row span{font-size:10px;color:var(--text-secondary);display:block;margin-top:5px}.review-row>div:last-child{display:flex;gap:8px;flex-wrap:wrap;flex-shrink:0}button{font:inherit;font-size:10px;padding:7px 9px;border:1px solid var(--border);border-radius:5px;background:var(--surface);color:var(--text);cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:650px){.review-row{align-items:flex-start;flex-direction:column}}</style>
